using System;
using System.Collections.Generic;
using UnityEngine;

namespace WildPartner.World
{
    /// <summary>
    /// Plants the world's vegetation and props at load from a baked placement list (generated by the editor
    /// world builder with a fixed seed, so every run is identical). Keeping ~20k instances out of the scene
    /// file keeps the scene small and lets stage 4 compare GPU Resident Drawer on/off on exactly the
    /// same content (FR-RD-06).
    /// </summary>
    public class VegetationSpawner : MonoBehaviour
    {
        [Serializable]
        public class Batch
        {
            public GameObject prefab;
            public List<Vector4> items = new List<Vector4>();   // x, y, z, packed (yaw degrees + 1000 * scale)
        }

        public List<Batch> batches = new List<Batch>();
        public int SpawnedCount { get; private set; }
        public static event Action<int> Spawned;

        void Awake() => Spawn();

        public void Spawn()
        {
            var t0 = Time.realtimeSinceStartup;
            Clear();
            foreach (var b in batches)
            {
                if (!b.prefab) continue;
                var parent = new GameObject(b.prefab.name).transform;
                parent.SetParent(transform, false);
                foreach (var it in b.items)
                {
                    float yaw = it.w % 1000f;
                    float scale = Mathf.Floor(it.w / 1000f) / 100f;
                    var go = Instantiate(b.prefab, new Vector3(it.x, it.y, it.z), Quaternion.Euler(0, yaw, 0), parent);
                    go.transform.localScale = Vector3.one * Mathf.Max(scale, 0.05f);
                    SpawnedCount++;
                }
            }
            Debug.Log($"[Vegetation] spawned {SpawnedCount} instances in {(Time.realtimeSinceStartup - t0) * 1000:0} ms");
            Spawned?.Invoke(SpawnedCount);
        }

        public void Clear()
        {
            for (int i = transform.childCount - 1; i >= 0; i--)
            {
                if (Application.isPlaying) Destroy(transform.GetChild(i).gameObject);
                else DestroyImmediate(transform.GetChild(i).gameObject);
            }
            SpawnedCount = 0;
        }

        public static float Pack(float yaw, float scale) => Mathf.Repeat(yaw, 360f) + 1000f * Mathf.Round(scale * 100f);
    }
}
